// 1. Get raw text safely
const item = $input.first();
// Ensure we have a string to work with
const rawText = (item.json && item.json.text) ? String(item.json.text) : "";

// --- HELPER FUNCTIONS ---

// Helper: Attempt to parse a clean string
function safeJSONParse(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    return null;
  }
}

// Helper: Sanitize common AI JSON errors (trailing commas, comments)
function cleanAndParse(str) {
  if (!str) return null;
  let cleaned = str;
  // Remove Markdown code blocks
  cleaned = cleaned.replace(/```(?:json|xml|text)?/gi, "").replace(/```/g, "");
  // Remove comments //...
  cleaned = cleaned.replace(/([^\\:]|^)\/\/.*/g, '$1');
  // Fix trailing commas (e.g., "key": "value", } -> "key": "value" })
  cleaned = cleaned.replace(/,(\s*[}\]])/g, '$1');

  return safeJSONParse(cleaned);
}

// Helper: Regex Fallback (The "Nuclear Option")
// If JSON parsing fails completely, this manually extracts the specific fields we need.
function manualExtract(text, key, type) {
  // Pattern looks for: "key": "captured_content"
  // It handles escaped quotes (\") inside the content correctly.
  const regex = new RegExp(`"${key}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`);

  // Special handling for Booleans
  if (type === 'boolean') {
    const boolRegex = new RegExp(`"${key}"\\s*:\\s*(true|false)`, 'i');
    const match = text.match(boolRegex);
    return match ? match[1].toLowerCase() === 'true' : false;
  }

  const match = text.match(regex);
  if (match && match[1]) {
    // We found the content! Now we parse just this string to handle escapes (like \n) correctly
    try {
      return JSON.parse(`"${match[1]}"`); 
    } catch (e) {
      // If even that fails, return raw string
      return match[1]; 
    }
  }
  return "";
}

// --- MAIN LOGIC ---

let parsedData = null;

// 1. Try to find the JSON block ({ ... })
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
  const jsonSubstring = rawText.substring(firstBrace, lastBrace + 1);

  // ATTEMPT 1: Parse the extracted block directly
  parsedData = safeJSONParse(jsonSubstring);

  // ATTEMPT 2: Clean syntax errors and parse
  if (!parsedData) {
    parsedData = cleanAndParse(jsonSubstring);
  }
}

// ATTEMPT 3: Manual Regex Extraction (Fallback if all parsing failed)
if (!parsedData) {
  // If the structure is broken, we just grab the values we need directly from the raw text
  parsedData = {
    replyMessage: manualExtract(rawText, "replyMessage", "string"),
    isModification: manualExtract(rawText, "isModification", "boolean"),
    updatedCvHtml: manualExtract(rawText, "updatedCvHtml", "string")
  };
}

// 4. Final Validation
// If even regex failed to find "replyMessage", we fall back to a default error.
const finalData = {
  isModification: parsedData.isModification === true,
  replyMessage: parsedData.replyMessage || "I encountered an error processing the CV. Please try again.",
  updatedCvHtml: parsedData.updatedCvHtml || ""
};

// 5. Return
return {
  json: {
    isModification: finalData.isModification,
    replyMessage: finalData.replyMessage,
    updatedCvHtml: finalData.updatedCvHtml 
  }
};

// Get the output from whichever LLM node ran
const aiOutput = $input.first().json.updatedCvHtml;

// Get the original input data from the start of the workflow
// IMPORTANT: Replace 'Edit Fields' with the actual name of your Set node
const initialData = $input.first().json.text;

// Get the base64 string, which might be empty
const base64String = $input.first().json.data|| '';

// 1. Clean up potential markdown code fences from the AI output
let cleanedHtml = aiOutput.replace(/^```html\s*/, '').replace(/```$/, '').trim();

// 2. Replace the placeholder with the actual base64 data
// If base64String is empty, it will replace the placeholder with nothing (effectively removing the image src if the AI messes up)
// If the placeholder isn't found (the "no image" path), this does nothing.
let finalHtml = cleanedHtml.replace('%%PROFILE_PICTURE_BASE64%%', base64String);

// Return the final, complete HTML string
return {
  html: finalHtml
};

